363	function Snapshot($src, $dst, [string[]]$extraXD, [string[]]$extraArgs = @()) {
364	    if (-not (Test-Path $src)) { Log "SNAP skip (missing): $src"; return }
365	    # Drive targets live under _MACHINE/Backups (2026-10-14). If the mount has not refreshed and cannot see
366	    # that folder, rsync would mkdir a SECOND copy on Drive. Check Backups, not just _MACHINE: on 2026-10-16
367	    # the mount showed _MACHINE but still listed Backups at the root. Skip and flag instead.
368	    if ($GDrive -and $dst.StartsWith("$GDrive/") -and -not (Test-Path "$GDrive/_MACHINE/Backups")) {
369	        $Errors.Add('backup-target-offline:GoogleDrive/_MACHINE')
370	        Log "SNAP skip (Drive _MACHINE not visible on the mount yet): $dst"; return
371	    }
372	    $xd = @('node_modules', '.venv', '__pycache__', '.git', 'cache', 'tmp') + $extraXD
373	    $ok = Invoke-Rsync $src $dst $xd @() $extraArgs
374	    if ($ok -ne $true) {
375	        $Errors.Add("snapshot:$([IO.Path]::GetFileName($dst))")
376	        Log "SNAP $src -> $dst : FAILED (rsync exit $LASTEXITCODE)"
377	    } else {
378	        Log "SNAP $src -> $dst : OK"
379	        $Results.Add(@{ kind='snapshot'; name=$dst; status='OK' })
380	    }
381	}
