425	# A receipt proves the destination accepted a write in THIS run.
426	function Write-Receipt($root, $runId) {
427	    if ($DryRun) { return $true }
428	    try {
429	        $rd = Join-Path $root '_receipts'
430	        New-Item -ItemType Directory -Force -Path $rd | Out-Null
431	        $f = Join-Path $rd "run-$runId.txt"
432	        Set-Content -LiteralPath $f -Value "run=$runId written=$(Get-Date -Format 'o') host=$(hostname)" -Encoding UTF8
433	        # CloudStorage mounts (Google Drive/OneDrive) can lag between write and
434	        # read-back visibility; retry briefly before declaring the receipt lost.
435	        for ($i = 0; $i -lt 6; $i++) {
436	            try {
437	                $back = Get-Content -LiteralPath $f -Raw -ErrorAction Stop
438	                if ($back -match [regex]::Escape($runId)) { return $true }
439	            } catch { }
440	            Start-Sleep -Seconds 5
441	        }
442	        return $false
443	    } catch { return $false }
444	}
