456	# --- 0. Platform guard ---
457	# This file is the macOS port. Every path below is macOS-specific: /usr/bin/rsync,
458	# $HOME/DEV, and the ~/Library/CloudStorage mount. On Windows it failed silently and
459	# WORSE than silently - snapshots logged "SNAP OK" off a stale $LASTEXITCODE, so the
460	# run reported success while copying nothing. That false receipt is the reason this
461	# guard exists. Refuse loudly instead of pretending.
462	# The Windows original (daily-backup.ps1.win-orig) is in git history, removed 2026-10-23:
463	# restore and re-port it before re-enabling KeystoneOS-DailyBackup on any Windows host.
464	# Note $IsMacOS is a PowerShell 6+ automatic variable; on Windows PowerShell 5.1 it is
465	# undefined, so -not $null still aborts. That is the intended outcome.
466	if (-not $IsMacOS) {
467	    Log "ABORT: daily-backup.ps1 is the macOS port and will not run on this platform. No backup ran, and no receipt was written. Restore daily-backup.ps1.win-orig from git history before re-enabling a scheduled task here."
468	    Log "===== daily-backup end: ABORTED (wrong platform) ====="
469	    exit 1
